    sb_irq_enable(SRC_TIMER0, sb_tick, PRIO_TICK);
    sb_irq_enable(SRC_SPI1, lcd_spi_done, PRIO_SPI1);
    JL_TIMER0->CNT = 0;
    JL_TIMER0->PRD = TICK_PRD;
    JL_TIMER0->CON = TICK_CON;
