    sb_test_leds();
#endif
    sb_irq_on();

#if defined(SB_TEST_FAULT)
    sb_test_fault();
#endif
#if defined(SB_TEST_STRAY)
    sb_test_stray();
#endif
#if defined(SB_TEST_BADINSN)
    sb_test_badinsn();
#endif

