/* Draws what is marked, oldest frame first, until it is done or this
 * block's drawing time is spent; then asks the tick to wake main for the
 * rest (the next millisecond) or for the next frame. */
static void draw_frame(void)
{
    u32 beats = sb_beacon.beats;

    if (beats - frame_beat < FRAME_MS && !drawn) {
        sb_wake_at = frame_beat + FRAME_MS;
        return;
    }
    if (!drawn)
        frame_beat = beats;
