/* One sample of the sine at a phase. */
static inline __attribute__((always_inline)) s32 osc(u32 phase)
{
    u32 i = phase >> (32 - SINE_BITS), f = phase >> (17 - SINE_BITS) & 0x7FFFu;
    s32 a = sine[i];

    return a + ((sine[i + 1] - a) * (s32)f >> 15);
