     * carriers' sum; written[] says which already hold this block's
     * first writer (so the first stores and the rest add). */
    static s32 bufs[2][FM_OPS + 1][AUDIO_FRAMES];
    s32 (*buf)[AUDIO_FRAMES] = bufs[v - (struct fm_voice *)0 >= 0 ? 0 : 0];
    const struct fm_algorithm *a = &fm_algorithms[v->algorithm];
    u32 written = 0, sounding = 0, n;
    int i;

    (void)buf;
    buf = bufs[cnum_core()];
    for (i = FM_OPS - 1; i >= 0; i--) {
        struct fm_op *o = &v->op[i];
        u32 dest = a->dest[i], to = dest == FM_TO_OUT ? FM_OPS : dest, kind = 0;
        s32 e = envelope(o), target, dg, fb0 = 0, dfb = 0;

