         * KNOB3's depth; a carrier its share of the output. */
        target = (s32)(((s64)e * fm_exp2_neg(o->fixed_att + (dest == FM_TO_OUT ? carrier_att[a->carriers]
                                                                                   : v->mod_att))) >> 30);
