/* The attenuation of a gain (2^-30, more than 0): -log2(gain) octaves,
 * the inverse of fm_exp2_neg, by bisection (only when a key is released
 * during an attack). */
static s32 att_of(s32 gain)
{
    s32 k = 0, lo = 0, hi = 65536;

    if (gain <= 0)
        return ATT_SILENT;
    if (gain >= GAIN_ONE)
        return 0;
    while (gain < GAIN_ONE) {
        gain <<= 1;
        k++;
