    /* gain is now in [2^30, 2^31): find f with 2^(f / 65536) = gain. */
    while (hi - lo > 1) {
        s32 mid = (lo + hi) / 2;
        if (exp2_frac((u32)mid) <= gain)
            lo = mid;
        else
