        s32 g = 1 << 16;
        for (n = 0; n < AUDIO_FRAMES; n++, g -= 1 << 10)
            mix[n] += (s32)(((s64)(buf[FM_OPS][n] >> 2) * g) >> 16);
        v->fade_done = 1;
        return;
    }
    for (n = 0; n < AUDIO_FRAMES; n++)
        mix[n] += buf[FM_OPS][n] >> 2;
}

