/* SR-7 reproduction: copying words of one struct into another. */
struct s { int a[8]; };
volatile struct s src = { { 1, 2, 3, 4, 5, 6, 7, 8 } };
struct s dst;
void copy(struct s *d, const struct s *p, int k)
